def trunc(M,k):
    u,s,vt=np.linalg.svd(M,full_matrices=False)
    return (u[:,:k]*s[:k])@vt[:k]
K=8
rows=[]
for la in range(3):
    for lb in range(la+1,4):
        for a in range(6):
            OV=trunc(H[la][a]['o']@H[la][a]['v'],K)
            for b in range(6):
                kb=trunc(H[lb][b]['k'],K); qb=trunc(H[lb][b]['q'],K)
                rows.append((la,a,lb,b,comp(kb,OV),comp(qb,OV)))
for j,nm in [(4,'K'),(5,'Q')]:
    v=np.array([r[j] for r in rows]); m,s=v.mean(),v.std()
    o=np.argsort(-v)[:10]
    print(nm,'mean %.3f sd %.3f: '%(m,s)+'; '.join('L%dH%d->L%dH%d %.2f(z%.1f)'%(rows[i][0],rows[i][1],rows[i][2],rows[i][3],v[i],(v[i]-m)/s) for i in o))
"}


