def frac(M,U):  # fraction of M's (row-space) energy in subspace U (384xk orthonormal)
    return np.linalg.norm(M@U)**2/np.linalg.norm(M)**2
rows=[]
for la in range(3):
    for a in range(6):
        Uo=np.linalg.svd(H[la][a]['o']@H[la][a]['v'],full_matrices=False)[0][:,:8]
        for lb in range(la+1,4):
            for b in range(6):
                fk=frac(trunc(H[lb][b]['k'],8),Uo); fq=frac(trunc(H[lb][b]['q'],8),Uo)
                rows.append((la,a,lb,b,fk,fq))
r=np.array([[x[4],x[5]] for x in rows])
d=r[:,0]-r[:,1]
o=np.argsort(-d)[:10]; o2=np.argsort(d)[:6]
print('baseline frac mean K %.3f Q %.3f (random 8/384=%.3f)'%(r[:,0].mean(),r[:,1].mean(),8/384))
print('K>>Q:', '; '.join('L%dH%d->L%dH%d k%.2f q%.2f'%(rows[i][0],rows[i][1],rows[i][2],rows[i][3],rows[i][4],rows[i][5]) for i in o))
print('Q>>K:', '; '.join('L%dH%d->L%dH%d k%.2f q%.2f'%(rows[i][0],rows[i][1],rows[i][2],rows[i][3],rows[i][4],rows[i][5]) for i in o2))
"}


